// The compiler throws an error if the function is provided a fifth argument which is not a collection...
{
	const c = new Float64Array( 3 );

	gcirculant( 'row-major', 3, c, 1, 10, 3 ); // $ExpectError
	gcirculant( 'row-major', 3, c, 1, true, 3 ); // $ExpectError
	gcirculant( 'row-major', 3, c, 1, false, 3 ); // $ExpectError
	gcirculant( 'row-major', 3, c, 1, null, 3 ); // $ExpectError
	gcirculant( 'row-major', 3, c, 1, undefined, 3 ); // $ExpectError
	gcirculant( 'row-major', 3, c, 1, {}, 3 ); // $ExpectError
	gcirculant( 'row-major', 3, c, 1, ( x: number ): number => x, 3 ); // $ExpectError
}

// The compiler throws an error if the function is provided a sixth argument which is not a number...
{
	const c = new Float64Array( 3 );
	const out = new Float64Array( 9 );

	gcirculant( 'row-major', 3, c, 1, out, '10' ); // $ExpectError
	gcirculant( 'row-major', 3, c, 1, out, true ); // $ExpectError
	gcirculant( 'row-major', 3, c, 1, out, false ); // $ExpectError
	gcirculant( 'row-major', 3, c, 1, out, null ); // $ExpectError
	gcirculant( 'row-major', 3, c, 1, out, undefined ); // $ExpectError
	gcirculant( 'row-major', 3, c, 1, out, [] ); // $ExpectError
	gcirculant( 'row-major', 3, c, 1, out, {} ); // $ExpectError
	gcirculant( 'row-major', 3, c, 1, out, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const c = new Float64Array( 3 );
	const out = new Float64Array( 9 );

	gcirculant(); // $ExpectError
	gcirculant( 'row-major' ); // $ExpectError
	gcirculant( 'row-major', 3 ); // $ExpectError
	gcirculant( 'row-major', 3, c ); // $ExpectError
	gcirculant( 'row-major', 3, c, 1 ); // $ExpectError
	gcirculant( 'row-major', 3, c, 1, out ); // $ExpectError
	gcirculant( 'row-major', 3, c, 1, out, 3, 10 ); // $ExpectError
}

// Attached to the main export is an `ndarray` method which returns a collection...
{
	const c = new Float64Array( 3 );
	const out = new Float64Array( 9 );

	gcirculant.ndarray( 3, c, 1, 0, out, 3, 1, 0 ); // $ExpectType Float64Array
	gcirculant.ndarray( 3, new AccessorArray( c ), 1, 0, new AccessorArray( out ), 3, 1, 0 ); // $ExpectType AccessorArray<number>
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	const c = new Float64Array( 3 );
	const out = new Float64Array( 9 );

	gcirculant.ndarray( '10', c, 1, 0, out, 3, 1, 0 ); // $ExpectError
	gcirculant.ndarray( true, c, 1, 0, out, 3, 1, 0 ); // $ExpectError
	gcirculant.ndarray( false, c, 1, 0, out, 3, 1, 0 ); // $ExpectError
	gcirculant.ndarray( null, c, 1, 0, out, 3, 1, 0 ); // $ExpectError
	gcirculant.ndarray( undefined, c, 1, 0, out, 3, 1, 0 ); // $ExpectError
	gcirculant.ndarray( [], c, 1, 0, out, 3, 1, 0 ); // $ExpectError
	gcirculant.ndarray( {}, c, 1, 0, out, 3, 1, 0 ); // $ExpectError
	gcirculant.ndarray( ( x: number ): number => x, c, 1, 0, out, 3, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a second argument which is not a collection...
