	gcirculant.ndarray( 3, c, 1, 0, out, 3, '10', 0 ); // $ExpectError
	gcirculant.ndarray( 3, c, 1, 0, out, 3, true, 0 ); // $ExpectError
	gcirculant.ndarray( 3, c, 1, 0, out, 3, false, 0 ); // $ExpectError
