	gcirculant.ndarray( 3, c, 1, 0, out, 3, 1, true ); // $ExpectError
	gcirculant.ndarray( 3, c, 1, 0, out, 3, 1, false ); // $ExpectError
	gcirculant.ndarray( 3, c, 1, 0, out, 3, 1, null ); // $ExpectError
	gcirculant.ndarray( 3, c, 1, 0, out, 3, 1, undefined ); // $ExpectError
