// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const c = new Float64Array( 3 );
	const out = new Float64Array( 9 );

	gcirculant.ndarray(); // $ExpectError
	gcirculant.ndarray( 3 ); // $ExpectError
	gcirculant.ndarray( 3, c ); // $ExpectError
	gcirculant.ndarray( 3, c, 1 ); // $ExpectError
	gcirculant.ndarray( 3, c, 1, 0 ); // $ExpectError
	gcirculant.ndarray( 3, c, 1, 0, out ); // $ExpectError
	gcirculant.ndarray( 3, c, 1, 0, out, 3 ); // $ExpectError
	gcirculant.ndarray( 3, c, 1, 0, out, 3, 1 ); // $ExpectError
	gcirculant.ndarray( 3, c, 1, 0, out, 3, 1, 0, 10 ); // $ExpectError
}
